-- ── Hand-written constraints ─────────────────────────────────────────────────
-- The API validates the same rules (src/modules/seo/domain/seo-publishing.ts); these stop
-- any other writer (SQL console, import script) from publishing an invalid page.
-- Additive only: one new table. No existing table, column or row is touched.
ALTER TABLE "public"."seo_pages"
  ALTER COLUMN "page_type" SET NOT NULL,
  ALTER COLUMN "slug" SET NOT NULL,
  ALTER COLUMN "path" SET NOT NULL,
  ALTER COLUMN "canonical_url" SET NOT NULL,
  ALTER COLUMN "indexing_status" SET NOT NULL,
  ALTER COLUMN "indexing_status" SET DEFAULT 'index',
  ALTER COLUMN "publication_status" SET NOT NULL,
  ALTER COLUMN "publication_status" SET DEFAULT 'draft',
  ALTER COLUMN "version" SET NOT NULL,
  ALTER COLUMN "version" SET DEFAULT 1,
  -- The route policy's page kinds (SeoEntityKind) plus static and landing pages.
  ADD CONSTRAINT "seo_pages_ck_page_type" CHECK ("page_type" IN (
    'static', 'landing', 'ashram', 'ashramCity', 'temple', 'pandit', 'product',
    'marketplaceCategory', 'marketplaceStore', 'event', 'circuit', 'destination', 'blog',
    'aarti', 'parking', 'volunteerJob')),
  -- Static, landing and city pages have no entity; every other type must name one.
  ADD CONSTRAINT "seo_pages_ck_entity" CHECK (
    ("page_type" IN ('static', 'landing', 'ashramCity', 'destination')) = ("entity_id" IS NULL)),
  -- Lowercase, no query, no trailing slash (except "/"), no "//".
  ADD CONSTRAINT "seo_pages_ck_path" CHECK (
    "path" ~ '^/([a-z0-9]+(-[a-z0-9]+)*(/[a-z0-9]+(-[a-z0-9]+)*)*)?$' AND char_length("path") <= 300),
  ADD CONSTRAINT "seo_pages_ck_slug" CHECK ("slug" ~ '^([a-z0-9]+(-[a-z0-9]+)*)?$' AND char_length("slug") <= 120),
  -- canonical_url is stored for the SOP, but can never disagree with path or point off-site.
  ADD CONSTRAINT "seo_pages_ck_canonical" CHECK ("canonical_url" = 'https://www.tirvona.com' || "path"),
  ADD CONSTRAINT "seo_pages_ck_lengths" CHECK (
    (char_length("seo_title") BETWEEN 1 AND 70 OR "seo_title" IS NULL) AND
    (char_length("meta_description") BETWEEN 1 AND 170 OR "meta_description" IS NULL) AND
    (char_length("h1") BETWEEN 1 AND 120 OR "h1" IS NULL)),
  ADD CONSTRAINT "seo_pages_ck_json" CHECK (
    ("content_json" IS NULL OR jsonb_typeof("content_json") = 'object') AND
    ("schema_json" IS NULL OR jsonb_typeof("schema_json") IN ('object', 'array')) AND
    ("pending" IS NULL OR jsonb_typeof("pending") = 'object')),
  ADD CONSTRAINT "seo_pages_ck_statuses" CHECK (
    "indexing_status" IN ('index', 'noindex') AND
    "publication_status" IN ('draft', 'in_review', 'approved', 'published', 'retired')),
  -- Nothing is published unverified or unapproved, and a retired page either redirects
  -- on-site or answers 410.
  ADD CONSTRAINT "seo_pages_ck_lifecycle" CHECK (
    ("publication_status" NOT IN ('approved', 'published') OR ("verified_at" IS NOT NULL AND "approved_by" IS NOT NULL)) AND
    ("publication_status" <> 'published' OR "published_at" IS NOT NULL) AND
    ("publication_status" <> 'retired' OR "retired_at" IS NOT NULL) AND
    ("redirect_to" IS NULL OR ("publication_status" = 'retired' AND "redirect_to" ~ '^/[a-z0-9/-]*$' AND "redirect_to" <> "path")));
